CREATE TABLE "t1" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY UNIQUE PRIMARY KEY NOT NULL DEFAULT 1,
  "name" varchar(255) DEFAULT 'x',
  "ratio" float DEFAULT -1.5,
  "flag" bool DEFAULT false,
  "ts" timestamp DEFAULT (now()),
  "arr" int[],
  "json" jsonb,
  PRIMARY KEY ("name")
);

CREATE UNIQUE INDEX "idx_id" ON "t1" USING HASH ("id");

CREATE INDEX ON "t1" ((lower(name)), "name");

COMMENT ON TABLE "t1" IS 'n';
